package httpapi

const masterSurveyHTMLV2 = `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Анкеты игроков</title><style>
:root{color-scheme:dark;--bg:#070b14;--panel:#111827;--panel2:#0c1320;--line:#d4a45338;--gold:#e7b85f;--violet:#b967f4;--text:#f3eadc;--muted:#929bac;font-family:Inter,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);background:radial-gradient(circle at 78% 0,#58216a3b,transparent 28%),radial-gradient(circle at 0 90%,#7a481c2f,transparent 27%),#070b14}.page{width:min(1220px,94vw);margin:auto;padding:34px 0 70px}header{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:24px}h1{font:700 clamp(38px,6vw,66px)/1 Georgia,serif;margin:8px 0}.eyebrow{color:var(--gold);letter-spacing:.16em;text-transform:uppercase;font-size:12px}.muted{color:var(--muted)}select,input,button{font:inherit}select,input{border:1px solid #ffffff22;background:#09111f;color:var(--text);border-radius:11px;padding:13px 14px;outline:0}select:focus,input:focus{border-color:var(--violet);box-shadow:0 0 0 3px #b967f422}.campaign{min-width:260px}.invite{display:grid;grid-template-columns:1fr 260px auto;gap:12px;align-items:center;padding:18px;border:1px solid var(--line);background:linear-gradient(125deg,#141a28e8,#20152be8);border-radius:16px;box-shadow:0 20px 60px #0006}.invite strong{font:600 20px Georgia,serif}.primary{border:1px solid #efbd77;background:linear-gradient(105deg,#58239a,#8b318e 55%,#d1834c);color:#fff3e1;padding:13px 18px;border-radius:11px;font-weight:750;cursor:pointer}.primary:disabled{opacity:.55}.linkout{grid-column:1/-1;color:#d9c6ed;overflow-wrap:anywhere;font-size:13px}.link-result{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid #ffffff18;border-radius:11px;background:#09111f}.link-result a{color:#d9a7ff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.copy{border:1px solid #b967f477;background:#321a49;color:#f5eaff;border-radius:9px;padding:9px 14px;font-weight:700;cursor:pointer;white-space:nowrap}.layout{display:grid;grid-template-columns:310px 1fr;gap:20px;margin-top:22px}.panel{border:1px solid var(--line);background:linear-gradient(145deg,#111927f2,#0b1320f2);border-radius:17px;box-shadow:0 25px 75px #0007}.list{padding:14px;max-height:720px;overflow:auto}.list-head{display:flex;justify-content:space-between;align-items:center;padding:8px 6px 14px}.list-head h2{font:600 20px Georgia;margin:0}.badge{color:#140d1c;background:var(--gold);border-radius:99px;padding:3px 9px;font-weight:800;font-size:12px}.person{width:100%;text-align:left;border:1px solid transparent;background:transparent;color:inherit;border-radius:12px;padding:13px;cursor:pointer;display:block;margin:4px 0}.person:hover{background:#ffffff08}.person.active{border-color:#bd70ed;background:linear-gradient(105deg,#48205f99,#261b3b);box-shadow:0 0 22px #a949df24}.person b,.person span{display:block}.person small{color:var(--muted)}.person .who{display:flex;gap:10px;align-items:center}.avatar{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:#161e2c;border:1px solid #d6a65266;color:var(--gold);font-weight:800}.detail{padding:24px}.empty{display:grid;place-items:center;min-height:380px;text-align:center;color:var(--muted)}.hero{display:flex;align-items:start;justify-content:space-between;gap:20px;border-bottom:1px solid #ffffff0d;padding-bottom:18px;margin-bottom:18px}.hero h2{font:600 32px Georgia;margin:4px 0}.identity{color:var(--gold);font-weight:700}.date{color:var(--muted);font-size:13px}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fact{padding:15px;border:1px solid #ffffff14;border-radius:12px;background:#09111fb8;min-height:90px}.fact.wide{grid-column:1/-1}.fact label{display:block;color:var(--gold);font-size:11px;letter-spacing:.11em;text-transform:uppercase;margin-bottom:8px}.fact p{white-space:pre-wrap;line-height:1.55;margin:0;color:#d7d9df}.error{color:#ff9ba8}@media(max-width:820px){.page{padding:20px 0;width:min(94vw,620px)}header{display:block}.campaign{width:100%;margin-top:12px}.invite{grid-template-columns:1fr}.invite>*{width:100%}.linkout{grid-column:auto}.link-result{align-items:stretch;flex-direction:column}.layout{grid-template-columns:1fr}.list{max-height:300px}.facts{grid-template-columns:1fr}.fact.wide{grid-column:auto}.detail{padding:17px}.hero h2{font-size:27px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><main class="page"><header><div><div class="eyebrow">Shadow Edge GM · кабинет мастера</div><h1>Анкеты игроков</h1><div class="muted">Персональные приглашения и ожидания вашей группы.</div></div><select class="campaign" id="campaign" aria-label="Кампания"></select></header>
<section class="invite"><div><strong>Пригласить игрока</strong><div class="muted">Введите имя для персональной ссылки или оставьте поле пустым для общей.</div></div><input id="player" maxlength="120" placeholder="Имя игрока — необязательно" autocomplete="off"><button class="primary" id="create">Создать ссылку</button><div class="linkout" id="linkout" aria-live="polite"></div></section>
<div class="layout"><aside class="panel list"><div class="list-head"><div><h2>Полученные ответы</h2><small class="muted">Правый клик — удалить</small></div><span class="badge" id="count">0</span></div><div id="people"></div></aside><section class="panel detail" id="detail"><div class="empty">Выберите игрока, чтобы открыть его анкету.</div></section></div></main>
<script>const c=document.querySelector('#campaign'),people=document.querySelector('#people'),detail=document.querySelector('#detail'),count=document.querySelector('#count'),player=document.querySelector('#player'),linkout=document.querySelector('#linkout'),create=document.querySelector('#create');let responses=[],selected='',currentURL='';const e=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));const value=v=>e(v||'Не указано');async function api(u,o){let r=await fetch(u,o),x=await r.json();if(!r.ok)throw Error(x.error?.message||'Не удалось выполнить запрос');return x.data}function label(x){return x.invitedPlayer||x.name||'Без имени'}function initials(x){return label(x).trim().slice(0,1).toUpperCase()||'?'}function date(v){try{return new Intl.DateTimeFormat('ru',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return v||''}}function field(name,v,wide=true){return '<div class="fact'+(wide?' wide':'')+'"><label>'+e(name)+'</label><p>'+value(v)+'</p></div>'}function renderDetail(){let x=responses.find(r=>r.id===selected);if(!x){detail.innerHTML='<div class="empty">Пока ответов нет. Создайте ссылку и отправьте её игроку.</div>';return}let source=x.invitedPlayer?'Персональное приглашение для '+e(x.invitedPlayer):'Ответ по общей ссылке';detail.innerHTML='<div class="hero"><div><div class="identity">'+source+'</div><h2>'+value(label(x))+'</h2><div class="muted">Как представился: '+value(x.name)+'</div></div><div class="date">'+e(date(x.submittedAt))+'</div></div><div class="facts">'+field('Желаемый мир / сеттинг',x.setting)+field('Опыт в НРИ и комфорт с правилами',x.inspirations)+field('Персонаж или роль',x.character)+field('Имя персонажа',x.characterName,false)+field('Предварительный класс',x.characterClass,false)+field('Раса / происхождение',x.ancestry,false)+field('Роль в группе',x.partyRole,false)+field('Короткая предыстория',x.backstory)+field('Тон кампании',x.tone)+field('Предпочтения по атмосфере',x.atmosphere)+field('Что особенно хочется увидеть',x.expectations)+field('Темы и границы',x.boundaries)+'</div>'}async function removeResponse(x){if(!confirm('Удалить анкету игрока «'+label(x)+'»? Это действие нельзя отменить.'))return;await api('/api/campaigns/'+encodeURIComponent(c.value)+'/survey-responses/'+encodeURIComponent(x.id),{method:'DELETE'});responses=responses.filter(r=>r.id!==x.id);if(selected===x.id)selected=responses[0]?.id||'';render()}function render(){count.textContent=responses.length;people.innerHTML=responses.length?responses.map(x=>'<button class="person '+(x.id===selected?'active':'')+'" data-id="'+e(x.id)+'"><span class="who"><i class="avatar">'+e(initials(x))+'</i><span><b>'+value(label(x))+'</b><small>'+e(date(x.submittedAt))+'</small></span></span></button>').join(''):'<p class="muted" style="padding:8px">Ответов ещё нет.</p>';people.querySelectorAll('.person').forEach(b=>{b.onclick=()=>{selected=b.dataset.id;render();renderDetail()};b.oncontextmenu=event=>{event.preventDefault();let x=responses.find(r=>r.id===b.dataset.id);if(x)removeResponse(x).catch(showError)}});renderDetail()}async function answers(){responses=await api('/api/campaigns/'+encodeURIComponent(c.value)+'/survey-responses');responses.sort((a,b)=>String(b.submittedAt).localeCompare(String(a.submittedAt)));if(!responses.some(x=>x.id===selected))selected=responses[0]?.id||'';render()}async function load(){let cs=await api('/api/campaigns');c.innerHTML=cs.map(x=>'<option value="'+e(x.id)+'">'+e(x.title)+'</option>').join('');if(cs.length)await answers();else detail.innerHTML='<div class="empty">Сначала создайте кампанию.</div>'}c.onchange=()=>{selected='';answers().catch(showError)};function showError(x){linkout.className='linkout error';linkout.textContent=x.message||'Произошла ошибка'}async function copyURL(){if(!currentURL)return;try{await navigator.clipboard.writeText(currentURL)}catch{let area=document.createElement('textarea');area.value=currentURL;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove()}let b=document.querySelector('#copy');if(b){b.textContent='Скопировано ✓';setTimeout(()=>b.textContent='Скопировать',1600)}}create.onclick=async()=>{let name=player.value.trim();create.disabled=true;linkout.className='linkout';linkout.textContent=name?'Создаю персональную ссылку…':'Создаю общую ссылку…';try{let x=await api('/api/campaigns/'+encodeURIComponent(c.value)+'/survey-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({playerName:name})});currentURL=x.url;let title=x.playerName?'Ссылка для '+e(x.playerName):'Общая ссылка для игроков';linkout.innerHTML='<b>'+title+'</b><div class="link-result"><a href="'+e(x.url)+'" target="_blank" rel="noopener">'+e(x.url)+'</a><button class="copy" id="copy" type="button">Скопировать</button></div>';document.querySelector('#copy').onclick=copyURL;player.value=''}catch(x){showError(x)}finally{create.disabled=false}};player.onkeydown=e=>{if(e.key==='Enter')create.click()};load().catch(showError);</script></body></html>`
